import { field, textarea, select, checkbox, htmlEscape, attrEscape, normalizeUrl } from "../tool-core.js";export default {form: `<div class="field-grid">${field({ id: "manifestName", label: "App name", value: "My Site" })}${field({ id: "manifestShort", label: "Short name", value: "My Site" })}${field({ id: "manifestStartUrl", label: "Start URL", value: "/" })}${select({ id: "manifestDisplay", label: "Display mode", value: "standalone", options: [{ label: "standalone", value: "standalone" },{ label: "fullscreen", value: "fullscreen" },{ label: "minimal-ui", value: "minimal-ui" },{ label: "browser", value: "browser" }]})}${field({ id: "manifestTheme", label: "Theme color", value: "#181715", type: "color" })}${field({ id: "manifestBg", label: "Background color", value: "#ffffff", type: "color" })}${field({ id: "manifestIcon192", label: "192x192 icon path", value: "/icons/icon-192.png" })}${field({ id: "manifestIcon512", label: "512x512 icon path", value: "/icons/icon-512.png" })}${select({ id: "manifestOrientation", label: "Orientation", value: "any", options: [{ label: "any", value: "any" },{ label: "portrait", value: "portrait" },{ label: "landscape", value: "landscape" },{ label: "natural", value: "natural" }]})}</div>`,generate(root) {const name = root.querySelector("#manifestName").value.trim();const shortName = root.querySelector("#manifestShort").value.trim();const startUrl = root.querySelector("#manifestStartUrl").value.trim() || "/";const display = root.querySelector("#manifestDisplay").value;const themeColor = root.querySelector("#manifestTheme").value.trim();const bgColor = root.querySelector("#manifestBg").value.trim();const icon192 = root.querySelector("#manifestIcon192").value.trim();const icon512 = root.querySelector("#manifestIcon512").value.trim();const orientation = root.querySelector("#manifestOrientation").value;const manifest = {name,short_name: shortName,start_url: startUrl,display,theme_color: themeColor,background_color: bgColor,orientation};const icons = [];if (icon192) icons.push({ src: icon192, sizes: "192x192", type: "image/png" });if (icon512) icons.push({ src: icon512, sizes: "512x512", type: "image/png" });if (icons.length) manifest.icons = icons;return {output: `${JSON.stringify(manifest, null, 2)}\n\n<link rel="manifest" href="/site.webmanifest">`};}};